import sys

def solve() -> None:
    data = list(map(int, sys.stdin.read().strip().split()))
    if not data:
        return
    n, m = data[0], data[1]
    target = data[2:2 + m]

    ops = []
    nxt = 1  # 下一个即将从传送带上取下的包裹编号

    for x in target:
        # 不断将队首包裹放入暂存箱，直到当前包裹编号超过 x
        while nxt <= x:
            ops.append("In")
            if nxt != x:
                # 不是目标包裹，立刻从暂存箱顶部丢弃
                ops.append("Out")
            nxt += 1
        # 此时栈顶为 x，保留不动，处理下一个目标

    print(",".join(ops))

if __name__ == "__main__":
    solve()
```

